import{Engine,esc}from'./base.js';import{drawPattern}from'./artwork.js';import{ConstructionState}from'./construction.js';
export function patternPoint(i,n=6,r=120){let a=i*2*Math.PI/n-Math.PI/2;return[300+r*Math.cos(a),220+r*Math.sin(a)]}
export default class GeoDraw extends Engine{
 constructor(h,c){super(h,c);this.model=new ConstructionState(c.chapter.artStepTips.length);this.tips=c.chapter.artStepTips;this.colour=c.chapter.palette?.[2]?.color||'#b95a37';this.secondary=c.chapter.palette?.[1]?.color||'#437c83';this.zoom=1;this.tools=true;this.auto=false;this.hold=0;this.reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;h.innerHTML=`<div class="geoHeading">${c.H({en:'Compass & Ruler Workshop',hi:'परकार और पटरी कार्यशाला'},3)}<p>${c.dual('Draw the first step, then use Next to construct the next one. Play runs the whole construction; Pause freezes it.','पहला चरण बनाएँ, फिर Next से अगला चरण बनाएँ। Play से पूरी रचना चलेगी; Pause से वहीं रुकेगी।')}</p></div><div class="geoSteps" role="group" aria-label="${c.dual('Construction steps','रचना के चरण')}">${this.tips.map((s,i)=>`<button data-geo-step="${i}" aria-current="${i===0?'step':'false'}">${i+1}. ${c.label(s.title.en,s.title.hi)}</button>`).join('')}</div><div class="geoWorkspace"><div><canvas class="artCanvas geoCanvas" width="1200" height="800" role="img" tabindex="0" aria-label="${c.dual(c.chapter.title.en+'; Enter draws, arrows review, Space plays or pauses',c.chapter.title.hi+'; Enter से बनाएँ, तीर से चरण देखें, Space से चलाएँ या रोकें')}"></canvas><article class="geoTip"></article><p class="geoCount" role="status"></p><progress class="geoProgress" max="${this.model.count}" value="0" aria-label="${c.dual('Construction progress','रचना की प्रगति')}"></progress></div><aside class="geoPreview"><h4>${c.label('Final colour preview','अंतिम रंग का पूर्वदृश्य')}</h4><canvas width="600" height="400" role="img" aria-label="${c.dual('Preview responds to both colour controls','दोनों रंग बदलने पर बदलता पूर्वदृश्य')}"></canvas><label>${c.label('Primary colour','मुख्य रंग')}<input data-geo-colour="primary" type="color" value="${this.colour}"></label><label>${c.label('Second colour','दूसरा रंग')}<input data-geo-colour="secondary" type="color" value="${this.secondary}"></label><div class="geoSwatches" role="group" aria-label="${c.dual('Primary colour presets','मुख्य रंग के विकल्प')}">${c.chapter.palette.map(p=>`<button data-geo-swatch="${p.color}" style="background:${p.color}" aria-label="${c.dual(p.name.en,p.name.hi)}" title="${c.dual(p.name.en,p.name.hi)}"></button>`).join('')}</div><p>${c.dual('Preview colours change now; the construction is filled in step 8.','पूर्वदृश्य का रंग अभी बदलेगा; रचना में रंग चरण 8 पर भरेगा।')}</p></aside></div><div class="engineTools geoControls"><button data-draw="prev">${c.label('← Previous','← पिछला')}</button><button data-draw="do">${c.label('Draw this step','यह चरण बनाएँ')}</button><button data-draw="next">${c.label('Next: draw →','अगला: बनाएँ →')}</button><button data-draw="download">${c.label('Prepare final PNG','अंतिम PNG तैयार करें')}</button></div><div class="engineTools"><label><input type="checkbox" data-geo-tools checked> ${c.label('Show compass / ruler','परकार / पटरी दिखाएँ')}</label><label>${c.label('Zoom','ज़ूम')}<input data-geo-zoom type="range" min="1" max="1.25" step="0.05" value="1"><output class="geoZoom">1×</output></label></div><p>${c.dual('Future steps unlock only after the preceding construction is complete. Arcs share the same radius; the guide tools are symbolic. Restart clears the construction; Reset view only restores zoom.','पिछली रचना पूरी होने पर ही आगे का चरण खुलेगा। चापों की त्रिज्या समान है; सहायक औज़ार सांकेतिक हैं। Restart रचना फिर शुरू करता है; Reset view केवल ज़ूम ठीक करता है।')}</p>`;
 this.canvas=h.querySelector('.geoCanvas');this.preview=h.querySelector('.geoPreview canvas');if(c.lowPower){this.canvas.width=600;this.canvas.height=400}
 this.on(h,'click',e=>{let step=e.target.closest('[data-geo-step]'),action=e.target.closest('[data-draw]')?.dataset.draw,swatch=e.target.closest('[data-geo-swatch]');if(swatch)this.setColour('primary',swatch.dataset.geoSwatch);if(step){this.stop();if(this.model.select(+step.dataset.geoStep))this.render()}if(action==='do')this.drawStep();if(action==='prev'){this.stop();this.model.previous();this.render()}if(action==='next'){this.stop();if(this.model.next())this.drawStep()}if(action==='download')this.preparePNG()});this.on(this.canvas,'click',()=>this.drawStep());this.on(this.canvas,'keydown',e=>{if(['Enter',' ','ArrowRight','ArrowLeft'].includes(e.key))e.preventDefault();if(e.key==='Enter')this.drawStep();if(e.key===' ')c.playing(this.pause());if(e.key==='ArrowRight'){this.stop();if(this.model.next())this.drawStep()}if(e.key==='ArrowLeft'){this.stop();this.model.previous();this.render()}});
 for(let input of h.querySelectorAll('[data-geo-colour]'))this.on(input,'input',()=>this.setColour(input.dataset.geoColour,input.value));this.on(h.querySelector('[data-geo-tools]'),'change',e=>{this.tools=e.target.checked;this.paint()});this.on(h.querySelector('[data-geo-zoom]'),'input',e=>{this.zoom=+e.target.value;h.querySelector('.geoZoom').textContent=this.zoom+'×';this.paint()});
 const q=c.chapter.spotStep;if(q){let box=document.createElement('div');box.className='geoObservation';box.innerHTML=`<label>${c.label(q.question.en,q.question.hi)}<select><option value="">${c.dual('Choose a step','चरण चुनें')}</option>${this.tips.map((s,i)=>`<option value="${i}">${i+1}. ${c.dual(s.title.en,s.title.hi)}</option>`).join('')}</select></label><p role="status"></p>`;h.append(box);this.on(box.querySelector('select'),'change',e=>{let ok=e.target.value!==''&&+e.target.value===q.correct;this.metrics.spot=ok;box.querySelector('p').textContent=c.dual(ok?'Correct. ':'Look again. ',ok?'सही। ':'फिर देखें। ')+c.text(q.reason);this.emit(box.querySelector('p').textContent)})}this.render();this.renderPreview()}
 setColour(which,value){if(which==='primary')this.colour=value;else this.secondary=value;this.host.querySelector(`[data-geo-colour="${which}"]`).value=value;this.metrics.selectedColour=1;this.clearExport();this.paint();this.renderPreview();this.emit(this.ctx.dual('Colour preview updated. The final fill uses both selected colours.','रंग पूर्वदृश्य बदला। अंतिम भराव में दोनों चुने रंग लगेंगे।'))}
 setLowPower(v){this.ctx.lowPower=v;this.canvas.width=v?600:1200;this.canvas.height=v?400:800;this.paint()}
 stop(){this.playing=false;this.auto=false;cancelAnimationFrame(this.frame);this.ctx.playing(false)}
 drawStep(){if(this.model.drawing&&this.playing)return;this.auto=false;if(!this.model.drawing)this.model.start();this.playing=true;this.ctx.playing(true);this.last=0;this.render();this.scheduleFrame()}
 pause(){if(this.playing){this.stop();this.render();return false}this.auto=true;this.playing=true;this.hold=0;this.last=0;if(!this.model.drawing){if(this.model.step<this.model.completed&&!this.model.finished)this.model.next();else if(this.model.finished&&this.model.step===this.model.count-1)this.model.select(0);this.model.start()}this.render();this.scheduleFrame();return true}
 scheduleFrame(){cancelAnimationFrame(this.frame);if(this.playing&&!document.hidden&&!this.abort.signal.aborted)this.frame=requestAnimationFrame(t=>this.tick(t))}
 tick(t){if(!this.playing||document.hidden)return;if(!this.last)this.last=t;let elapsed=(t-this.last)/1000;if(this.ctx.lowPower&&elapsed<1/32){this.scheduleFrame();return}let delta=elapsed*this.speed;this.last=t;if(this.model.drawing){let complete=this.model.advance(this.reduced?1:delta);this.paint();if(complete){this.hold=0;this.render();if(!this.auto){this.stop();return}}}else if(this.auto){this.hold+=delta;if(this.hold>=.65){if(this.model.step===this.model.count-1){this.stop();return}this.model.next();this.model.start();this.render()}}this.scheduleFrame()}
 paint(){let g=this.canvas.getContext('2d'),m=this.model;g.setTransform(this.canvas.width/600,0,0,this.canvas.height/400,0,0);g.fillStyle='#fffaf0';g.fillRect(0,0,600,400);g.translate(300,200);g.scale(this.zoom,this.zoom);g.translate(-300,-200);drawPattern(g,this.ctx.chapter.drawingKind,m.shown,this.colour,{secondary:this.secondary,labels:this.labels,tools:this.tools,activeStep:m.drawing?m.step+1:0,progress:m.progress});if(m.completed===0&&!m.drawing){g.strokeStyle='#c2a06c';g.setLineDash([4,4]);g.beginPath();g.arc(300,200,12,0,Math.PI*2);g.stroke();g.setLineDash([]);g.fillStyle='#586c5c';g.font='14px Inter, sans-serif';g.textAlign='center';g.fillText(this.ctx.dual('Draw step 1 to place centre O','केंद्र O रखने के लिए चरण 1 बनाएँ'),300,310);g.textAlign='start'}}
 renderPreview(){let g=this.preview.getContext('2d');g.setTransform(1,0,0,1,0,0);g.fillStyle='#fffaf0';g.fillRect(0,0,600,400);drawPattern(g,this.ctx.chapter.drawingKind,8,this.colour,{secondary:this.secondary,clean:true})}
 render(){let c=this.ctx,m=this.model,s=this.tips[m.step];this.paint();this.host.querySelector('.geoTip').innerHTML=c.H({en:`Step ${m.step+1} / ${m.count} — ${s.title.en}`,hi:`चरण ${m.step+1} / ${m.count} — ${s.title.hi}`},4)+`<p>${esc(c.text(s.tip))}</p>`;this.host.querySelector('.geoCount').textContent=c.dual('Completed','पूरे चरण')+`: ${m.completed} / ${m.count} · `+c.dual(m.drawing?(this.playing?'Drawing this step…':'Paused — use Play or Draw to resume.'):m.step===m.count-1&&m.finished?'Construction complete. Prepare the PNG or review earlier steps.':m.step<m.completed?'This step is complete. Next draws the following step.':'Choose Draw this step to begin.',m.drawing?(this.playing?'यह चरण बन रहा है…':'रुका है — Play या बनाएँ से जारी रखें।'):m.step===m.count-1&&m.finished?'रचना पूरी है। PNG तैयार करें या पिछले चरण देखें।':m.step<m.completed?'यह चरण पूरा है। Next अगला चरण बनाएगा।':'शुरू करने के लिए यह चरण बनाएँ चुनें।');this.host.querySelector('progress').value=m.completed;this.host.querySelector('[data-draw="prev"]').disabled=m.step===0;this.host.querySelector('[data-draw="next"]').disabled=m.drawing||m.step>=m.completed||m.step===m.count-1;this.host.querySelector('[data-draw="do"]').disabled=m.drawing&&this.playing;this.host.querySelector('[data-draw="download"]').disabled=!m.finished;for(let b of this.host.querySelectorAll('[data-geo-step]')){let i=+b.dataset.geoStep;b.disabled=i>m.completed;b.setAttribute('aria-current',i===m.step?'step':'false');b.classList.toggle('completed',i<m.completed)}if(this.lastSelected!==m.step){let chip=this.host.querySelector(`[data-geo-step="${m.step}"]`),rail=this.host.querySelector('.geoSteps'),r=chip.getBoundingClientRect(),rr=rail.getBoundingClientRect();rail.scrollLeft+=r.left-rr.left-(rail.clientWidth-chip.offsetWidth)/2;this.lastSelected=m.step}this.metrics.completed=m.completed;this.metrics.step=m.completed-1;this.emit(this.host.querySelector('.geoCount').textContent+' '+c.text(s.tip))}
 clearExport(){this.exportRequest=(this.exportRequest||0)+1;if(this.exportURL)URL.revokeObjectURL(this.exportURL);this.exportURL=null;this.host.querySelector('.pngDownload')?.remove()}
 async preparePNG(){if(!this.model.finished)return;this.clearExport();const token=this.exportRequest;let canvas=document.createElement('canvas');canvas.width=1200;canvas.height=800;let g=canvas.getContext('2d');g.scale(2,2);g.fillStyle='#fffaf0';g.fillRect(0,0,600,400);drawPattern(g,this.ctx.chapter.drawingKind,8,this.colour,{secondary:this.secondary,clean:true});const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(this.abort.signal.aborted||token!==this.exportRequest)return;if(!blob){this.emit(this.ctx.dual('Could not prepare the image. Please try again.','चित्र तैयार नहीं हुआ। फिर प्रयास करें।'));return}this.exportURL=URL.createObjectURL(blob);let a=document.createElement('a');a.className='pngDownload';a.download='kala-darshan-'+this.ctx.chapter.id+'.png';a.href=this.exportURL;a.textContent=this.ctx.dual('Save final PNG ↓','अंतिम PNG सुरक्षित करें ↓');this.host.append(a);this.metrics.download=1;this.emit(this.ctx.dual('PNG ready. Select Save final PNG to download the completed drawing.','PNG तैयार है। पूरा चित्र डाउनलोड करने के लिए अंतिम PNG सुरक्षित करें चुनें।'));a.focus()}
 resetView(){this.zoom=1;this.host.querySelector('[data-geo-zoom]').value='1';this.host.querySelector('.geoZoom').textContent='1×';this.paint()}
 setLabels(v){this.labels=v;this.paint()}
 destroy(){this.clearExport();this.stop();super.destroy()}
}
